// swift-tools-version:6.0
// earshot app. The probe (../probe) stays as the lab for experiments.
// Each module depends on EarshotCore only, and talks to the others through its protocols.
// Only EarshotApp depends on all modules. Language mode: Swift 5 (see docs/BUILD-PLAN.md).
// Threads do not edit this file. The one exception: T1 adds the TranscribeCpp binary target and its linker settings.
import PackageDescription

let modules = ["EarshotSpeech", "EarshotRouter", "EarshotActions", "EarshotDiscovery", "EarshotInput", "EarshotUI"]

let package = Package(
    name: "earshot",
    platforms: [.macOS("26.0")],
    products: [
        .executable(name: "earshot", targets: ["EarshotApp"]),
        .library(name: "EarshotCore", targets: ["EarshotCore"]),
    ],
    targets: [
        .target(name: "EarshotCore", path: "Sources/EarshotCore"),
        .testTarget(name: "EarshotCoreTests", dependencies: ["EarshotCore"], path: "Tests/EarshotCoreTests"),
        .executableTarget(name: "EarshotApp", dependencies: ["EarshotCore"] + modules.map { .target(name: $0) },
                          path: "Sources/EarshotApp"),
    ]
    + modules.map { .target(name: $0, dependencies: ["EarshotCore"], path: "Sources/\($0)") }
    + modules.map { .testTarget(name: "\($0)Tests", dependencies: [.target(name: $0), "EarshotCore"], path: "Tests/\($0)Tests") },
    swiftLanguageModes: [.v5]
)
